// normalize ট্রি
function normNode(node) {
  if (typeof node === 'string') {
    const [k, id] = node.split(':');
    if (k === 'f') {
      const f = FORMS[id];
      return { id: 'form-' + id, title: f.title, icon: '📄', kind: 'form', formId: id };
    }
    const a = ART_BY_ID[id];
    return { id, title: a ? a.title : id, icon: '📖', kind: 'article' };
  }
  {
    const children = node.sub.map(normNode);
    // সাব-টপিক কার্ডের ছোট বর্ণনা — প্রথম আর্টিকেলের summary থেকে
    const firstArt = node.sub.find((s) => typeof s === 'string' && s.startsWith('a:'));
    const sm = firstArt ? ART_BY_ID[firstArt.slice(2)] : null;
    return { id: node.id, title: node.t, icon: node.i || '📁', kind: 'folder', children, desc: sm ? sm.summary : '' };
  }
}
const SECTIONS = Object.fromEntries(Object.entries(TREE).map(([tid, arr]) => [tid, arr.map(normNode)]));

